-- Monthly history for multi-year trends (idempotent)
CREATE TABLE IF NOT EXISTS "MonthlyMetric" (
  "id" TEXT NOT NULL,
  "year" INTEGER NOT NULL,
  "month" INTEGER NOT NULL,
  "metric" TEXT NOT NULL,
  "value" DOUBLE PRECISION NOT NULL,
  "source" TEXT NOT NULL DEFAULT 'import',
  CONSTRAINT "MonthlyMetric_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "MonthlyMetric_year_month_metric_key" ON "MonthlyMetric"("year","month","metric");
CREATE INDEX IF NOT EXISTS "MonthlyMetric_year_idx" ON "MonthlyMetric"("year");
